export const KIND = {"id":16,"example":{"id":"E16","kind":16,"source":"aether","statement":["Write a function `digit_sum::is_even_sum(const std::string& digits)` that returns whether the sum of the digits in the text is even.","Limits: 1 ≤ length of the text ≤ 100; the text holds only digits."],"examples":[],"tests":[],"solution":{"lines":["#pragma once","","#include <string>","","namespace digit_sum {","","bool is_even_sum(const std::string& digits)","{","    int total {0};","    for (const char digit : digits) {","        total += digit - '0';","    }","    return total % 2 == 0;","}","","}  // namespace digit_sum"],"frame":[0,2,4,15],"labels":[{"at":6,"level":1,"text":"Write a function that adds to a total, then gives back an answer from the total."},{"at":6,"level":0,"text":"Give the function a `const std::string&` parameter, which reads the caller's string without copying it."},{"at":8,"level":2,"text":"Start the total at zero."},{"at":9,"level":2,"text":"Add the value of each digit to the total."},{"at":10,"level":0,"text":"Turn a digit character into its value with `digit - '0'`."},{"at":12,"level":2,"text":"Give back whether 2 divides the total."}],"blanks":[]}},"trace":{"id":"T16","lines":["#include <iostream>","#include <print>","","bool even_total(int n)","{","    int total {0};","    for (int i {1}; i <= n; ++i) {","        total += i;","    }","    return total % 2 == 0;","}","","int main()","{","    int n {0};","    std::cin >> n;","    std::println(\"{}\", even_total(n));","}"],"columns":["n","total","i"],"inputs":["2\n","4\n"],"rows":[{"line":15,"values":["0","",""]},{"line":16,"values":["2","",""]},{"line":6,"values":["2","0",""]},{"line":7,"values":["2","0","1"]},{"line":8,"values":["2","1","1"]},{"line":7,"values":["2","1","2"]},{"line":8,"values":["2","3","2"]},{"line":7,"values":["2","3",""]},{"line":10,"values":["2","3",""]},{"line":17,"values":["2","",""]}],"output":"true\n"},"traces":[],"problems":{"16.01":{"id":"16.01","kind":16,"source":"exercism","statement":["Write a function `luhn::valid(const std::string& text)` that returns whether the text is a valid number by this rule.","Spaces in the text are dropped first.","The text is not valid when it holds any other character that is not a digit, or fewer than 2 digits.","Starting from the last digit, double every second digit, and take 9 from a doubled digit above 9.","The text is valid when 10 divides the sum of the digits so changed.","Limits: 0 ≤ length of text ≤ 100; text holds printable ASCII characters."],"examples":[{"input":"single digit strings can not be valid","output":""}],"tests":[{"input":"a single zero is invalid","output":""},{"input":"a simple valid SIN that remains valid if reversed","output":""},{"input":"a simple valid SIN that becomes invalid if reversed","output":""},{"input":"a valid Canadian SIN","output":""},{"input":"invalid Canadian SIN","output":""},{"input":"invalid credit card","output":""},{"input":"invalid long number with an even remainder","output":""},{"input":"invalid long number with a remainder divisible by 5","output":""},{"input":"valid number with an even number of digits","output":""},{"input":"valid number with an odd number of spaces","output":""},{"input":"valid strings with a non-digit added at the end become invalid","output":""},{"input":"valid strings with punctuation included become invalid","output":""},{"input":"valid strings with symbols included become invalid","output":""},{"input":"single zero with space is invalid","output":""},{"input":"more than a single zero is valid","output":""},{"input":"input digit 9 is correctly converted to output digit 9","output":""},{"input":"very long input is valid","output":""},{"input":"valid luhn with an odd number of digits and non zero first digit","output":""},{"input":"using ascii value for non-doubled non-digit isn't allowed","output":""},{"input":"using ascii value for doubled non-digit isn't allowed","output":""},{"input":"non-numeric, non-space char in the middle with a sum that's divisible by 10 isn't allowed","output":""}],"solution":{"lines":["#pragma once","","#include <cctype>","#include <ranges>","#include <string>","","namespace luhn {","","bool valid(const std::string& text)","{","    int total {0};","    int count {0};","    for (const char character : std::views::reverse(text)) {","        if (character == ' ') {","            continue;","        }","        if (!std::isdigit(character)) {","            return false;","        }","        int digit {character - '0'};","        if (count % 2 == 1) {","            digit *= 2;","        }","        if (digit > 9) {","            digit -= 9;","        }","        total += digit;","        ++count;","    }","    return count > 1 && total % 10 == 0;","}","","}  // namespace luhn"],"frame":[0,2,3,4,6,32],"labels":[{"at":8,"level":1,"text":"Write a function that adds to a total, then gives back an answer from the total."},{"at":10,"level":2,"text":"Start the total and the count of digits at zero."},{"at":12,"level":2,"text":"Add each digit from the last, doubled at every second, less 9 above 9."},{"at":29,"level":2,"text":"Give back whether there are 2 digits or more and 10 divides the total."}],"blanks":[{"line":8,"from":11,"to":34},{"line":10,"from":15,"to":16},{"line":26,"from":17,"to":22},{"line":29,"from":11,"to":39}]},"fn":{"slug":"luhn","commit":"8d139cb0","header":"luhn.h","name":"luhn_test.cpp","test":"#include \"luhn.h\"\n#ifdef EXERCISM_TEST_SUITE\n#include <catch2/catch.hpp>\n#else\n#include \"test/catch.hpp\"\n#endif\n\nTEST_CASE(\"single digit strings can not be valid\",\n          \"[792a7082-feb7-48c7-b88b-bbfec160865e]\") {\n    REQUIRE(false == luhn::valid(\"1\"));\n}\n\n#if defined(EXERCISM_RUN_ALL_TESTS)\n\nTEST_CASE(\"a single zero is invalid\",\n          \"[698a7924-64d4-4d89-8daa-32e1aadc271e]\") {\n    REQUIRE(false == luhn::valid(\"0\"));\n}\n\nTEST_CASE(\"a simple valid SIN that remains valid if reversed\",\n          \"[73c2f62b-9b10-4c9f-9a04-83cee7367965]\") {\n    REQUIRE(true == luhn::valid(\"059\"));\n}\n\nTEST_CASE(\"a simple valid SIN that becomes invalid if reversed\",\n          \"[9369092e-b095-439f-948d-498bd076be11]\") {\n    REQUIRE(true == luhn::valid(\"59\"));\n}\n\nTEST_CASE(\"a valid Canadian SIN\", \"[8f9f2350-1faf-4008-ba84-85cbb93ffeca]\") {\n    REQUIRE(true == luhn::valid(\"055 444 285\"));\n}\n\nTEST_CASE(\"invalid Canadian SIN\", \"[1cdcf269-6560-44fc-91f6-5819a7548737]\") {\n    REQUIRE(false == luhn::valid(\"055 444 286\"));\n}\n\nTEST_CASE(\"invalid credit card\", \"[656c48c1-34e8-4e60-9a5a-aad8a367810a]\") {\n    REQUIRE(false == luhn::valid(\"8273 1232 7352 0569\"));\n}\n\nTEST_CASE(\"invalid long number with an even remainder\",\n          \"[20e67fad-2121-43ed-99a8-14b5b856adb9]\") {\n    REQUIRE(false == luhn::valid(\"1 2345 6789 1234 5678 9012\"));\n}\n\nTEST_CASE(\"invalid long number with a remainder divisible by 5\",\n          \"[7e7c9fc1-d994-457c-811e-d390d52fba5e]\") {\n    REQUIRE(false == luhn::valid(\"1 2345 6789 1234 5678 9013\"));\n}\n\nTEST_CASE(\"valid number with an even number of digits\",\n          \"[ad2a0c5f-84ed-4e5b-95da-6011d6f4f0aa]\") {\n    REQUIRE(true == luhn::valid(\"095 245 88\"));\n}\n\nTEST_CASE(\"valid number with an odd number of spaces\",\n          \"[ef081c06-a41f-4761-8492-385e13c8202d]\") {\n    REQUIRE(true == luhn::valid(\"234 567 891 234\"));\n}\n\nTEST_CASE(\"valid strings with a non-digit added at the end become invalid\",\n          \"[bef66f64-6100-4cbb-8f94-4c9713c5e5b2]\") {\n    REQUIRE(false == luhn::valid(\"059a\"));\n}\n\nTEST_CASE(\"valid strings with punctuation included become invalid\",\n          \"[2177e225-9ce7-40f6-b55d-fa420e62938e]\") {\n    REQUIRE(false == luhn::valid(\"055-444-285\"));\n}\n\nTEST_CASE(\"valid strings with symbols included become invalid\",\n          \"[ebf04f27-9698-45e1-9afe-7e0851d0fe8d]\") {\n    REQUIRE(false == luhn::valid(\"055# 444$ 285\"));\n}\n\nTEST_CASE(\"single zero with space is invalid\",\n          \"[08195c5e-ce7f-422c-a5eb-3e45fece68ba]\") {\n    REQUIRE(false == luhn::valid(\" 0\"));\n}\n\nTEST_CASE(\"more than a single zero is valid\",\n          \"[12e63a3c-f866-4a79-8c14-b359fc386091]\") {\n    REQUIRE(true == luhn::valid(\"0000 0\"));\n}\n\nTEST_CASE(\"input digit 9 is correctly converted to output digit 9\",\n          \"[ab56fa80-5de8-4735-8a4a-14dae588663e]\") {\n    REQUIRE(true == luhn::valid(\"091\"));\n}\n\nTEST_CASE(\"very long input is valid\",\n          \"[b9887ee8-8337-46c5-bc45-3bcab51bc36f]\") {\n    REQUIRE(true == luhn::valid(\"9999999999 9999999999 9999999999 9999999999\"));\n}\n\nTEST_CASE(\"valid luhn with an odd number of digits and non zero first digit\",\n          \"[8a7c0e24-85ea-4154-9cf1-c2db90eabc08]\") {\n    REQUIRE(true == luhn::valid(\"109\"));\n}\n\nTEST_CASE(\"using ascii value for non-doubled non-digit isn't allowed\",\n          \"[39a06a5a-5bad-4e0f-b215-b042d46209b1]\") {\n    REQUIRE(false == luhn::valid(\"055b 444 285\"));\n}\n\nTEST_CASE(\"using ascii value for doubled non-digit isn't allowed\",\n          \"[f94cf191-a62f-4868-bc72-7253114aa157]\") {\n    REQUIRE(false == luhn::valid(\":9\"));\n}\n\nTEST_CASE(\n    // clang-format off\n    \"non-numeric, non-space char in the middle with a sum that's divisible by 10 isn't allowed\",\n    // clang-format on\n    \"[8b72ad26-c8be-49a2-b99c-bcc3bf631b33]\") {\n    REQUIRE(false == luhn::valid(\"59%59\"));\n}\n\n#endif\n","setup":[],"calls":[{"call":"luhn::valid(\"1\")","expected":"false"}]}},"16.02":{"id":"16.02","kind":16,"source":"exercism","statement":["Write a function `isbn_verifier::is_valid(const std::string& isbn)` that returns `true` when the text is a valid ISBN-10, else `false`.","Leave out every `-`. What is left must be exactly 10 characters: 9 digits, then a last character that is a digit or `X`, where `X` stands for 10.","Any other character, or an `X` in any other place, makes it not valid.","With d1 to d10 the 10 values in order, it is valid when (d1 × 10 + d2 × 9 + d3 × 8 + … + d9 × 2 + d10 × 1) mod 11 is 0.","Limits: 0 ≤ length of the text ≤ 14."],"examples":[{"input":"valid_isbn","output":""}],"tests":[{"input":"invalid_isbn_check_digit","output":""},{"input":"valid_isbn_with_a_check_digit_of_10","output":""},{"input":"check_digit_is_a_character_other_than_x","output":""},{"input":"invalid_check_digit_in_isbn_is_not_treated_as_zero","output":""},{"input":"invalid_character_in_isbn_is_not_treated_as_zero","output":""},{"input":"x_is_only_valid_as_a_check_digit","output":""},{"input":"valid_isbn_without_separating_dashes","output":""},{"input":"isbn_without_separating_dashes_and_x_as_check_digit","output":""},{"input":"isbn_without_check_digit_and_dashes","output":""},{"input":"too_long_isbn_and_no_dashes","output":""},{"input":"too_short_isbn","output":""},{"input":"isbn_without_check_digit","output":""},{"input":"check_digit_of_x_should_not_be_used_for_0","output":""},{"input":"empty_isbn","output":""},{"input":"input_is_9_characters","output":""},{"input":"invalid_characters_are_not_ignored_after_checking_length","output":""},{"input":"invalid_characters_are_not_ignored_before_checking_length","output":""},{"input":"input_is_too_long_but_contains_a_valid_isbn","output":""},{"input":"only_one_check_digit_is_allowed","output":""},{"input":"x_is_not_substituted_by_the_value_10","output":""}],"solution":{"lines":["#pragma once","","#include <cctype>","#include <string>","","namespace isbn_verifier {","","bool is_valid(const std::string& isbn)","{","    int total {0};","    int count {0};","    for (const char character : isbn) {","        if (std::isdigit(character) && count < 10) {","            total += (character - '0') * (10 - count);","            ++count;","        } else if (character == 'X' && count == 9) {","            total += 10;","            ++count;","        } else if (character != '-') {","            return false;","        }","    }","    return count == 10 && total % 11 == 0;","}","","}  // namespace isbn_verifier"],"frame":[0,2,3,5,25],"labels":[{"at":7,"level":1,"text":"Write a function that adds to a total, then gives back an answer from the total."},{"at":9,"level":2,"text":"Start the total and the count of digits at zero."},{"at":11,"level":2,"text":"Add each digit times 10 less the count, or 10 for an `X` at the end, and give back false for any other character but `-`."},{"at":22,"level":2,"text":"Give back whether there are 10 digits and 11 divides the total."}],"blanks":[{"line":7,"from":14,"to":37},{"line":9,"from":15,"to":16},{"line":13,"from":21,"to":53},{"line":22,"from":11,"to":41}]},"fn":{"slug":"isbn-verifier","commit":"8d139cb0","header":"isbn_verifier.h","name":"isbn_verifier_test.cpp","test":"#include \"isbn_verifier.h\"\n#ifdef EXERCISM_TEST_SUITE\n#include <catch2/catch.hpp>\n#else\n#include \"test/catch.hpp\"\n#endif\n\nTEST_CASE(\"valid_isbn\") { REQUIRE(isbn_verifier::is_valid(\"3-598-21508-8\")); }\n\n#if defined(EXERCISM_RUN_ALL_TESTS)\n\nTEST_CASE(\"invalid_isbn_check_digit\") {\n    REQUIRE_FALSE(isbn_verifier::is_valid(\"3-598-21508-9\"));\n}\n\nTEST_CASE(\"valid_isbn_with_a_check_digit_of_10\") {\n    REQUIRE(isbn_verifier::is_valid(\"3-598-21507-X\"));\n}\n\nTEST_CASE(\"check_digit_is_a_character_other_than_x\") {\n    REQUIRE_FALSE(isbn_verifier::is_valid(\"3-598-21507-A\"));\n}\n\nTEST_CASE(\"invalid_check_digit_in_isbn_is_not_treated_as_zero\") {\n    REQUIRE_FALSE(isbn_verifier::is_valid(\"4-598-21507-B\"));\n}\n\nTEST_CASE(\"invalid_character_in_isbn_is_not_treated_as_zero\") {\n    REQUIRE_FALSE(isbn_verifier::is_valid(\"3-598-P1581-X\"));\n}\n\nTEST_CASE(\"x_is_only_valid_as_a_check_digit\") {\n    REQUIRE_FALSE(isbn_verifier::is_valid(\"3-598-2X507-9\"));\n}\n\nTEST_CASE(\"valid_isbn_without_separating_dashes\") {\n    REQUIRE(isbn_verifier::is_valid(\"3598215088\"));\n}\n\nTEST_CASE(\"isbn_without_separating_dashes_and_x_as_check_digit\") {\n    REQUIRE(isbn_verifier::is_valid(\"359821507X\"));\n}\n\nTEST_CASE(\"isbn_without_check_digit_and_dashes\") {\n    REQUIRE_FALSE(isbn_verifier::is_valid(\"359821507\"));\n}\n\nTEST_CASE(\"too_long_isbn_and_no_dashes\") {\n    REQUIRE_FALSE(isbn_verifier::is_valid(\"3598215078X\"));\n}\n\nTEST_CASE(\"too_short_isbn\") { REQUIRE_FALSE(isbn_verifier::is_valid(\"00\")); }\n\nTEST_CASE(\"isbn_without_check_digit\") {\n    REQUIRE_FALSE(isbn_verifier::is_valid(\"3-598-21507\"));\n}\n\nTEST_CASE(\"check_digit_of_x_should_not_be_used_for_0\") {\n    REQUIRE_FALSE(isbn_verifier::is_valid(\"3-598-21515-X\"));\n}\n\nTEST_CASE(\"empty_isbn\") { REQUIRE_FALSE(isbn_verifier::is_valid(\"\")); }\n\nTEST_CASE(\"input_is_9_characters\") {\n    REQUIRE_FALSE(isbn_verifier::is_valid(\"134456729\"));\n}\n\nTEST_CASE(\"invalid_characters_are_not_ignored_after_checking_length\") {\n    REQUIRE_FALSE(isbn_verifier::is_valid(\"3132P34035\"));\n}\n\nTEST_CASE(\"invalid_characters_are_not_ignored_before_checking_length\") {\n    REQUIRE_FALSE(isbn_verifier::is_valid(\"3598P215088\"));\n}\n\nTEST_CASE(\"input_is_too_long_but_contains_a_valid_isbn\") {\n    REQUIRE_FALSE(isbn_verifier::is_valid(\"98245726788\"));\n}\nTEST_CASE(\"only_one_check_digit_is_allowed\") {\n    REQUIRE_FALSE(isbn_verifier::is_valid(\"3-598-21508-96\"));\n}\n\nTEST_CASE(\"x_is_not_substituted_by_the_value_10\") {\n    REQUIRE_FALSE(isbn_verifier::is_valid(\"3-598-2X507-5\"));\n}\n#endif\n","setup":[],"calls":[{"call":"isbn_verifier::is_valid(\"3-598-21508-8\")","expected":"true"}]}},"16.03":{"id":"16.03","kind":16,"source":"exercism","statement":["Write a function `armstrong_numbers::is_armstrong_number(int number)` that returns `true` when the number equals the sum of its digits, each raised to the power of how many digits the number has, else `false`.","For example, 153 returns `true`, since 1³ + 5³ + 3³ = 153, and 10 returns `false`, since 1² + 0² = 1.","Each number from 0 to 9 returns `true`.","Limits: 0 ≤ number ≤ 9 999 999."],"examples":[{"input":"zero_is_an_armstrong_number","output":""}],"tests":[{"input":"single_digit_numbers_are_armstrong_numbers","output":""},{"input":"there_are_no_2_digit_armstrong_numbers","output":""},{"input":"three_digit_number_that_is_an_armstrong_number","output":""},{"input":"three_digit_number_that_is_not_an_armstrong_number","output":""},{"input":"four_digit_number_that_is_an_armstrong_number","output":""},{"input":"four_digit_number_that_is_not_an_armstrong_number","output":""},{"input":"seven_digit_number_that_is_an_armstrong_number","output":""},{"input":"seven_digit_number_that_is_not_an_armstrong_number","output":""}],"solution":{"lines":["#pragma once","","#include <string>","","namespace armstrong_numbers {","","bool is_armstrong_number(int number)","{","    const std::string digits {std::to_string(number)};","    const int count {static_cast<int>(digits.size())};","    int total {0};","    for (const char digit : digits) {","        int power {1};","        for (int index {0}; index < count; ++index) {","            power *= digit - '0';","        }","        total += power;","    }","    return total == number;","}","","}  // namespace armstrong_numbers"],"frame":[0,2,4,21],"labels":[{"at":6,"level":1,"text":"Write a function that adds to a total, then gives back an answer from the total."},{"at":8,"level":2,"text":"Make a string of the number's digits, and count them."},{"at":10,"level":2,"text":"Start the total at zero."},{"at":11,"level":2,"text":"Add each digit to the power of the count to the total."},{"at":18,"level":2,"text":"Give back whether the total equals the number."}],"blanks":[{"line":6,"from":25,"to":35},{"line":8,"from":30,"to":52},{"line":10,"from":15,"to":16},{"line":16,"from":17,"to":22},{"line":18,"from":11,"to":26}]},"fn":{"slug":"armstrong-numbers","commit":"8d139cb0","header":"armstrong_numbers.h","name":"armstrong_numbers_test.cpp","test":"#ifdef EXERCISM_TEST_SUITE\n#include <catch2/catch.hpp>\n#else\n#include \"test/catch.hpp\"\n#endif\n#include \"armstrong_numbers.h\"\n\n// Armstrong-numbers exercise test case data version 1.1.0\n\nTEST_CASE(\"zero_is_an_armstrong_number\") {\n    REQUIRE(armstrong_numbers::is_armstrong_number(0));\n}\n\n#if defined(EXERCISM_RUN_ALL_TESTS)\nTEST_CASE(\"single_digit_numbers_are_armstrong_numbers\") {\n    REQUIRE(armstrong_numbers::is_armstrong_number(5));\n}\n\nTEST_CASE(\"there_are_no_2_digit_armstrong_numbers\") {\n    REQUIRE_FALSE(armstrong_numbers::is_armstrong_number(10));\n}\n\nTEST_CASE(\"three_digit_number_that_is_an_armstrong_number\") {\n    REQUIRE(armstrong_numbers::is_armstrong_number(153));\n}\n\nTEST_CASE(\"three_digit_number_that_is_not_an_armstrong_number\") {\n    REQUIRE_FALSE(armstrong_numbers::is_armstrong_number(100));\n}\n\nTEST_CASE(\"four_digit_number_that_is_an_armstrong_number\") {\n    REQUIRE(armstrong_numbers::is_armstrong_number(9474));\n}\n\nTEST_CASE(\"four_digit_number_that_is_not_an_armstrong_number\") {\n    REQUIRE_FALSE(armstrong_numbers::is_armstrong_number(9475));\n}\n\nTEST_CASE(\"seven_digit_number_that_is_an_armstrong_number\") {\n    REQUIRE(armstrong_numbers::is_armstrong_number(9926315));\n}\n\nTEST_CASE(\"seven_digit_number_that_is_not_an_armstrong_number\") {\n    REQUIRE_FALSE(armstrong_numbers::is_armstrong_number(9926314));\n}\n#endif  // !EXERCISM_RUN_ALL_TESTS\n","setup":[],"calls":[{"call":"armstrong_numbers::is_armstrong_number(0)","expected":"true"}]}}}}
